// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.entityimport androidx.room.ColumnInfoimport androidx.room.Entityimport androidx.room.Indeximport androidx.room.PrimaryKey/** * NOUS — Native crash log (v2.1). * * Tracks native C++ crashes (SIGSEGV, SIGABRT) for diagnostics. * Written by [CrashWatchdogService] when a native crash is detected * via the async-signal-safe pipe handler. * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§17 Database Additions</a> */@Entity(    tableName = "native_crash_logs",    indices = [Index("timestamp")],)data class NativeCrashLogEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "signal_code")    val signalCode: Int,    @ColumnInfo(name = "signal_name")    val signalName: String,  // "SIGSEGV", "SIGABRT"    @ColumnInfo(name = "fault_address")    val faultAddress: String? = null,    @ColumnInfo(name = "active_model")    val activeModel: String? = null,    @ColumnInfo(name = "timestamp")    val timestamp: Long,)